mapper.select:
SELECT DATE_FORMAT(a.SEND_DATE,'%Y-%m-%d hh24:mi') sendDateStr, DATE_FORMAT(a.RECEIVE_DATE,'%Y-%m-%d hh24:mi') receiveDateStr,
a.SEND_STATUS sendStatus, a.RECEIVE_STATUS receiveStatus, a.CHANNEL_CODE channelCode, a.FILE_NAME fileName, f.NAME reportCategoryName, ftp.REPORT_CATEGORY reportCategory, ftp.PROD_ID prodId, reveal.REPORT_NAME reportName, DATE_FORMAT(ftp.STATR_DATE,'%Y-%m-%d') statrDateStr, DATE_FORMAT(ftp.END_DATE,'%Y-%m-%d') endDateStr, ftp.ID id, ftp.REVEAL_ID revealId, ftp.REPORT_ID reportId
FROM REP_FTP_DETAIL ftp left join REP_FTP_DETAIL_MSG a on ftp.ID=a.DETAIL_ID left join REP_FTP_PATH f on ftp.REPORT_CATEGORY=f.ID left join REP_REVEAL reveal on ftp.REVEAL_ID=reveal.ID WHERE 1=1
AND DATE_FORMAT(a.SEND_DATE,'%Y-%m-%d') >= #{sendDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(a.SEND_DATE,'%Y-%m-%d') <= #{sendDateEnd,jdbcType=VARCHAR}
and a.SEND_STATUS in
#{item}
and a.RECEIVE_STATUS in
#{item}
and a.FILE_NAME like concat_ws('', '%',#{fileName,jdbcType=VARCHAR},'%')
and a.CHANNEL_CODE in
#{item}
and ftp.REPORT_CATEGORY in
#{item}
and (ftp.PROD_ID in
null) or ftp.PROD_ID in (
#{item}
)
order by ftp.CREATE_TIME DESC
